// top-level FuncDecl, so the literal escapes its statement cap of 50. The hiss scanner
// measures a package-level literal as a function of its own and reports it without
// enforcing it.
var StatementLiteral = func() int {
	total := 0
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	total++
	return total
}
